import numpy as np
L=[l.split() for l in open('opt_gfn2b.xyz').read().split('\n')[2:] if l.strip()]
el=[a[0] for a in L]; P=np.array([[float(x) for x in a[1:4]] for a in L])
cov={'H':0.31,'C':0.76,'N':0.71,'Zn':1.22,'In':1.42}
n=len(el)
D=np.linalg.norm(P[:,None]-P[None],axis=-1)
bonds=[[] for _ in range(n)]
for i in range(n):
    for j in range(i+1,n):
        if D[i,j]<1.3*(cov[el[i]]+cov[el[j]]):
            bonds[i].append(j); bonds[j].append(i)
from collections import Counter
print(Counter((el[i],len(bonds[i])) for i in range(n)))
for i in range(n):
    if el[i] in('In','Zn','N'): print(i,el[i],[(j,el[j],round(D[i,j],2)) for j in bonds[i]])
